const demoStorageKey='sso-editor-demo-v1';
let demoContent={events:[],profiles:[]};
function loadDemoContent(){try{const saved=JSON.parse(localStorage.getItem(demoStorageKey)||'null');if(saved&&Array.isArray(saved.events)&&Array.isArray(saved.profiles))demoContent=saved}catch{}}
function applyDemoContent(){if(currentSitePage!=='manage')return;loadDemoContent();for(const e of demoContent.events){if(!/^\d{4}-\d{2}-\d{2}$/.test(e.calendarDate)||!e.id?.startsWith('demo-'))continue;const title=escapeOnboard(e.title||'');const desc=escapeOnboard(e.desc||'');events.push({...e,title:P(title,title),desc:P(desc,desc),detail:P(desc,desc),date:P('DEMO EVENT','فعالية تجريبية'),poster:tr('Community<br>gathering','لقاء<br>مجتمعي'),category:'community',style:'nile',source:social,demo:true,venue:escapeOnboard(e.venue||''),time:escapeOnboard(e.time||''),access:escapeOnboard(e.access||'')})}demoContent.profiles.forEach((p,i)=>{if(p&&executives[i]){executives[i].name=escapeOnboard(p.name);executives[i].role=P(escapeOnboard(p.role),escapeOnboard(p.role));executives[i].initials=escapeOnboard(p.name.split(/\s+/).map(w=>w[0]||'').slice(0,2).join(''))}})}
function communityHeading(kicker,title,desc){return `<div class="sectiontop"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2><p>${desc}</p></div></div>`}
const contactTopics=[['question','Ask a question','اسأل سؤالاً','Something you’d like to know about SSO.','أي شيء تود معرفته عن المنظمة.'],['feedback','Share feedback','شارك رأيك','An idea, suggestion or something we could improve.','فكرة أو اقتراح أو شيء يمكننا تحسينه.'],['complaint','Raise a concern','قدّم شكوى','A complaint or concern you want the team to hear.','شكوى أو ملاحظة تريد إيصالها للفريق.'],['partnership','Partner with us','تعاون معنا','Collaborations, sponsorships and campus partnerships.','تعاون ورعاية وشراكات جامعية.'],['joining','Get involved','شارك معنا','Membership, volunteering or helping with an event.','عضوية أو تطوع أو مساعدة في فعالية.'],['other','Something else','موضوع آخر','Whatever brings you here, start a conversation.','مهما كان موضوعك، ابدأ بالتواصل.']];
function contactSection(){return `<section class="section" id="contact">${communityHeading(tr('We’re listening','نحن نسمعك'),tr('One place to reach us.','مكان واحد للتواصل معنا.'),tr('Questions, ideas, concerns or a new collaboration. Choose what brings you here.','أسئلة أو أفكار أو شكاوى أو تعاون جديد. اختر موضوع تواصلك.'))}<p class="demo-notice">${tr('Online messages are opening soon. For now, reach us on Instagram.','التواصل بالنموذج متاح قريباً. تواصل معنا حالياً عبر إنستغرام.')}</p><div class="contact-layout"><div><div class="contact-topics" role="group" aria-label="${tr('Contact topics','مواضيع التواصل')}">${contactTopics.map(([id,en,ar,de,da])=>`<button type="button" class="contact-topic" data-contact-topic="${id}" aria-pressed="${id==='question'}"><strong>${tr(en,ar)} </strong><small>${tr(de,da)}</small></button>`).join('')}</div><div class="contact-real"><span class="eyebrow">${tr('Say hello on Instagram','قول مرحب على إنستغرام')}</span><p>${tr('Send a message to the club on Instagram.','أرسل رسالة للمنظمة على إنستغرام.')}</p><a class="textlink" href="${social}" target="_blank" rel="noopener noreferrer">@sso.uofa </a></div></div><div class="community-card contact-form-card"><form class="demo-form" id="contact-demo"><span class="tag">${tr('01 · WRITE YOUR MESSAGE','٠١ · اكتب رسالتك')}</span><input id="contact-topic" type="hidden" value="question"><p class="contact-selected"><span>${tr('Topic','الموضوع')}</span><strong id="contact-selected-topic">${tr('Ask a question','اسأل سؤالاً')}</strong></p><label for="contact-name">${tr('Name','الاسم')}</label><input id="contact-name" required autocomplete="name" maxlength="80"><label for="contact-email">${tr('Email','البريد الإلكتروني')}</label><input id="contact-email" required type="email" autocomplete="email" maxlength="254"><p class="small-note">${tr('Name and email are required. Online delivery is not available yet.','الاسم والبريد مطلوبان. الإرسال عبر الموقع غير متاح بعد.')}</p><label for="contact-message">${tr('Your message','رسالتك')}</label><textarea id="contact-message" required maxlength="2000" rows="6" placeholder="${tr('What would you like us to know?','ماذا تود أن تخبرنا؟')}"></textarea><button class="button">${tr('Review message','راجع الرسالة')} </button></form><div id="contact-review" hidden tabindex="-1"></div><p id="contact-result" role="status"></p></div></div></section>`}
const guideLinks=[
['Find your way','اعرف طريقك','Campus maps and building information.','خرائط الجامعة ومعلومات المباني.','https://www.ualberta.ca/en/maps.html'],
['Settle into campus','استقر في الجامعة','International Student & Visitor Services.','خدمات الطلاب والزوار الدوليين.','https://www.ualberta.ca/en/international/international-student-services/index.html'],
['Find your study spot','اختر مكان دراستك','Libraries, study spaces and research support.','مكتبات وأماكن دراسة ودعم بحثي.','https://library.ualberta.ca/'],
['Ask for support','اطلب الدعم','Accessibility and accommodations information.','معلومات إمكانية الوصول والتسهيلات.','https://www.ualberta.ca/en/current-students/accessibility-resources/index.html'],
['Explore student support','استكشف دعم الطلاب','UASU Cares resource directory.','دليل موارد اتحاد الطلاب.','https://uasucares.su.ualberta.ca/en/']];
function guideSection(){return `<section class="section" id="guide">${communityHeading(tr('Your first few weeks','أسابيعك الأولى'),tr('New here? You belong.','جديد هنا؟ في مكان ليك.'),tr('A few starting points for finding your feet at UAlberta.','نقاط بداية تساعدك على التأقلم في جامعة ألبرتا.'))}<div class="guide-welcome"><span lang="ar">أهلاً بيك</span><div><h3>${tr('Find one familiar face.','ابدأ بوجه مألوف.')}</h3><p>${tr('Introduce yourself to SSO, explore an upcoming gathering, and ask what’s happening on campus. You don’t need to know anyone already.','عرّف نفسك للمنظمة واستكشف اللقاءات القادمة واسأل عن أنشطة الجامعة. لا تحتاج لمعرفة أحد مسبقاً.')}</p><a class="textlink" href="/sso-uofa/#join">${tr('Explore joining','استكشف الانضمام')} </a></div></div><div class="community-grid">${guideLinks.map(([en,ar,de,da,url],i)=>`<a class="community-card guide-link" href="${url}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">0${i+1} </span><h3>${tr(en,ar)}</h3><p>${tr(de,da)}</p><small>${tr('Official resource','مورد رسمي')}</small></a>`).join('')}<a class="community-card guide-link" href="/sso-uofa/resources.html#prayer"><span class="eyebrow">06 </span><h3>${tr('Prayer & campus resources','الصلاة وموارد الجامعة')}</h3><p>${tr('Explore the website’s prayer card and student resource links.','استكشف بطاقة مواقيت الصلاة وروابط الموارد الطلابية.')}</p></a></div><p class="small-note">${tr('Resource links reviewed 9 October 2026. Independent services, not SSO partnerships. Check each provider for current details.','رُوجعت روابط الموارد في ٩ أكتوبر ٢٠٢٦. خدمات مستقلة وليست شراكات للمنظمة. راجع الجهة المقدمة للتفاصيل الحالية.')}</p></section>`}
function gallerySection(){return `<section class="section" id="gallery">${communityHeading(tr('Memories in the making','ذكريات بتتكوّن'),tr('Our community, in pictures.','مجتمعنا بالصور.'),tr('Shared tables. New friendships. Moments worth keeping.','لمة وصداقات جديدة ولحظات تستحق أن تبقى.'))}<div class="upcoming-empty"><span class="eyebrow">${tr('More memories soon','ذكريات أكثر قريباً')}</span><h3>${tr('The album is on its way.','ألبوم الصور في الطريق.')}</h3><p>${tr('For now, explore moments from the community on Instagram.','تابع لحظات المجتمع حالياً على إنستغرام.')}</p><a class="button light" href="${social}" target="_blank" rel="noopener noreferrer">${tr('See our Instagram','استعرض إنستغرام')} </a></div><div hidden><input id="gallery-file" type="file"><p id="gallery-status"></p><img id="gallery-preview" hidden alt=""></div></section>`}
function manageSection(){return `<section class="section" id="manage">${communityHeading(tr('For the next executive team','للفريق التنفيذي القادم'),tr('Make it yours.','خلي الموقع يعبر عنكم.'),tr('Try an editing dashboard without changing the public website.','جرّب لوحة تحرير دون تغيير الموقع العام.'))}<p class="demo-notice">${tr('Local demo · Event and profile changes are saved only in this browser. No login, shared database or publishing is connected. Use fictional content.','تجربة محلية · تُحفظ تعديلات الفعاليات والملفات في هذا المتصفح فقط. لا يوجد تسجيل دخول أو قاعدة بيانات مشتركة أو نشر. استخدم محتوى تجريبياً.')}</p><div class="community-two"><form class="community-card demo-form" id="editor-event"><h3>${tr('Create a sample event','إنشاء فعالية تجريبية')}</h3><label for="editor-title">${tr('Event title','عنوان الفعالية')}</label><input id="editor-title" required maxlength="100"><label for="editor-date">${tr('Date · Edmonton','التاريخ · إدمونتون')}</label><input id="editor-date" type="date" required><label for="editor-time">${tr('Time (optional)','الوقت (اختياري)')}</label><input id="editor-time" type="time"><label for="editor-venue">${tr('Venue (sample)','المكان (تجريبي)')}</label><input id="editor-venue" maxlength="120" placeholder="${tr('e.g. Campus venue — demo','مثلاً مكان في الجامعة — تجريبي')}"><label for="editor-access">${tr('Accessibility notes (sample)','ملاحظات إمكانية الوصول (تجريبية)')}</label><input id="editor-access" maxlength="200"><label for="editor-description">${tr('Description','الوصف')}</label><textarea id="editor-description" required maxlength="500" rows="3"></textarea><button class="button">${tr('Save local demo event','حفظ فعالية محلية تجريبية')}</button><p id="editor-event-status" role="status"></p></form><div><form class="community-card demo-form" id="editor-profile"><h3>${tr('Edit a profile locally','تعديل ملف محلياً')}</h3><label for="editor-person">${tr('Choose profile','اختر الملف')}</label><select id="editor-person">${executives.map((e,i)=>`<option value="${i}">${e.name}</option>`).join('')}</select><label for="editor-name">${tr('Display name','الاسم المعروض')}</label><input id="editor-name" required maxlength="80"><label for="editor-role">${tr('Role','المنصب')}</label><input id="editor-role" required maxlength="100"><button class="button">${tr('Save local profile','حفظ الملف محلياً')}</button><p id="editor-profile-status" role="status"></p></form><div class="community-card editor-list"><h3>${tr('Local events','الفعاليات المحلية')}</h3><div id="editor-event-list"></div><button class="button light" id="editor-reset">${tr('Reset all demo edits','إعادة ضبط التعديلات التجريبية')}</button><p id="editor-reset-status" role="status"></p><a class="textlink" href="/sso-uofa/events.html">${tr('Preview events page','معاينة صفحة الفعاليات')} </a></div></div></div></section>`}
function extraSections(){return volunteerSection()+contactSection()+guideSection()+gallerySection()+manageSection()}
function saveDemo(){try{localStorage.setItem(demoStorageKey,JSON.stringify(demoContent));return true}catch{return false}}
function bindCommunity(){
const c=document.querySelector('#contact-demo'),topic=document.querySelector('#contact-topic'),review=document.querySelector('#contact-review'),result=document.querySelector('#contact-result');
const selectTopic=()=>{const selected=contactTopics.find(x=>x[0]===topic.value);document.querySelector('#contact-selected-topic').textContent=tr(selected[1],selected[2]);document.querySelectorAll('[data-contact-topic]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.contactTopic===topic.value))};topic.onchange=selectTopic;
document.querySelectorAll('[data-contact-topic]').forEach(b=>b.onclick=()=>{c.hidden=false;review.hidden=true;result.textContent='';topic.value=b.dataset.contactTopic;selectTopic();document.querySelector('#contact-message').focus()});
c.onsubmit=e=>{e.preventDefault();if(!c.reportValidity())return;const message=document.querySelector('#contact-message');if(!message.value.trim()){message.setCustomValidity(tr('Please enter a message.','يرجى كتابة رسالة.'));message.reportValidity();message.oninput=()=>message.setCustomValidity('');return}const nameField=document.querySelector('#contact-name');if(!nameField.value.trim()){nameField.setCustomValidity(tr('Please enter your name.','يرجى كتابة اسمك.'));nameField.reportValidity();nameField.oninput=()=>nameField.setCustomValidity('');return}const chosen=contactTopics.find(x=>x[0]===topic.value),name=document.querySelector('#contact-name').value.trim(),email=document.querySelector('#contact-email').value.trim();review.innerHTML=`<span class="tag">${tr('02 · REVIEW YOUR MESSAGE','٠٢ · راجع رسالتك')}</span><h3>${tr(chosen[1],chosen[2])}</h3><dl class="contact-summary"><dt>${tr('From','من')}</dt><dd>${escapeOnboard(name)||tr('Anonymous','دون اسم')}</dd><dt>${tr('Email','البريد الإلكتروني')}</dt><dd dir="auto">${escapeOnboard(email)||tr('Not provided','لم يُقدّم')}</dd></dl><p class="contact-message" dir="auto">${escapeOnboard(message.value.trim())}</p><p class="small-note">${tr('Online delivery is not available yet. Use Instagram to send your message.','الإرسال عبر الموقع غير متاح بعد. استخدم إنستغرام لإرسال رسالتك.')}</p><div class="contact-actions"><button type="button" class="button" id="contact-finish">${tr('Messaging opens soon','الإرسال متاح قريباً')}</button><button type="button" class="button light" id="contact-edit">${tr('Edit message','تعديل الرسالة')}</button></div>`;c.hidden=true;review.hidden=false;review.focus();document.querySelector('#contact-edit').onclick=()=>{review.hidden=true;c.hidden=false;message.focus()};document.querySelector('#contact-finish').onclick=()=>{review.innerHTML=`<span class="tag">${tr('ONLINE DELIVERY · COMING SOON','الإرسال عبر الموقع · قريباً')}</span><h3>${tr('Reach us on Instagram.','تواصل معنا عبر إنستغرام.')}</h3><p>${tr('Your message has not been delivered. Please use @sso.uofa on Instagram while online messaging is unavailable.','لم تُرسل رسالتك. تواصل عبر حساب المنظمة على إنستغرام حتى إتاحة الإرسال عبر الموقع.')}</p><button type="button" class="button light" id="contact-again">${tr('Start another message','ابدأ رسالة أخرى')}</button>`;c.reset();result.textContent=tr('No message sent.','لم تُرسل رسالة.');document.querySelector('#contact-again').onclick=()=>{review.hidden=true;review.innerHTML='';c.hidden=false;result.textContent='';selectTopic();topic.focus()}}};
document.querySelectorAll('[data-gallery-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-gallery-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelectorAll('[data-gallery-category]').forEach(x=>x.hidden=b.dataset.galleryFilter!=='all'&&x.dataset.galleryCategory!==b.dataset.galleryFilter)});
document.querySelector('#gallery-file').onchange=e=>{const f=e.target.files[0],status=document.querySelector('#gallery-status'),img=document.querySelector('#gallery-preview');if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5*1024*1024){status.textContent=tr('Choose a PNG, JPEG or WebP image under 5 MB.','اختر صورة PNG أو JPEG أو WebP أصغر من ٥ ميغابايت.');return}if(img.dataset.objectUrl)URL.revokeObjectURL(img.dataset.objectUrl);const url=URL.createObjectURL(f);img.src=url;img.dataset.objectUrl=url;img.hidden=false;status.textContent=tr('Local preview only. Nothing uploaded.','معاينة محلية فقط. لم تُرفع الصورة.')};
const list=()=>{document.querySelector('#editor-event-list').innerHTML=demoContent.events.length?demoContent.events.map(e=>`<p><b>${escapeOnboard(e.title)}</b><br><small>${escapeOnboard(e.calendarDate)}</small> <button class="textlink" data-remove-demo="${escapeOnboard(e.id)}">${tr('Remove','حذف')}</button></p>`).join(''):`<p>${tr('No local demo events yet.','لا توجد فعاليات محلية تجريبية بعد.')}</p>`;document.querySelectorAll('[data-remove-demo]').forEach(b=>b.onclick=()=>{demoContent.events=demoContent.events.filter(e=>e.id!==b.dataset.removeDemo);saveDemo();list()})};list();
document.querySelector('#editor-event').onsubmit=e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;demoContent.events.push({id:'demo-'+crypto.randomUUID(),title:document.querySelector('#editor-title').value.trim(),calendarDate:document.querySelector('#editor-date').value,time:document.querySelector('#editor-time').value,venue:document.querySelector('#editor-venue').value.trim(),access:document.querySelector('#editor-access').value.trim(),desc:document.querySelector('#editor-description').value.trim()});if(saveDemo()){f.reset();document.querySelector('#editor-event-status').textContent=tr('Saved in this browser. Open Events to preview it.','حُفظت في هذا المتصفح. افتح الفعاليات لمعاينتها.');list()}else document.querySelector('#editor-event-status').textContent=tr('Browser storage unavailable. Changes cannot be retained.','التخزين غير متاح. لا يمكن حفظ التعديلات.')};
const profile=()=>{const p=executives[Number(document.querySelector('#editor-person').value)];document.querySelector('#editor-name').value=p.name.replace(/&amp;/g,'&');document.querySelector('#editor-role').value=t(p.role)};profile();document.querySelector('#editor-person').onchange=profile;document.querySelector('#editor-profile').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;const i=Number(document.querySelector('#editor-person').value);demoContent.profiles[i]={name:document.querySelector('#editor-name').value.trim(),role:document.querySelector('#editor-role').value.trim()};document.querySelector('#editor-profile-status').textContent=saveDemo()?tr('Local profile saved. Open Our team to preview.','حُفظ الملف محلياً. افتح فريقنا للمعاينة.'):tr('Browser storage unavailable.','التخزين غير متاح.')};
document.querySelector('#editor-reset').onclick=()=>{try{localStorage.removeItem(demoStorageKey);location.reload()}catch{document.querySelector('#editor-reset-status').textContent=tr('Unable to reset browser storage.','تعذر إعادة ضبط التخزين.')}}
}
function eventExtraDetails(e){const unknown=tr('Not confirmed · check original announcement','غير مؤكد · راجع الإعلان الأصلي');return `<dl class="event-info"><dt>${tr('Location','المكان')}</dt><dd>${e.venue|| (e.id==='bbq'?'Main Quad':unknown)}</dd><dt>${tr('Time · Edmonton','الوقت · إدمونتون')}</dt><dd>${e.time||unknown}</dd><dt>${tr('Accessibility','إمكانية الوصول')}</dt><dd>${e.access||unknown}</dd><dt>${tr('Registration','التسجيل')}</dt><dd>${e.demo?tr('Demo only · registration is not connected','تجريبي فقط · التسجيل غير متصل'):e.calendarDate&&e.calendarDate<campusToday()?tr('Archived · registration closed','مؤرشف · التسجيل مغلق'):unknown}</dd></dl>${e.demo?`<p class="demo-notice">${tr('Sample event created in your browser. Not an official club announcement.','فعالية تجريبية في متصفحك وليست إعلاناً رسمياً للمنظمة.')}</p><button class="button light" id="demo-rsvp">${tr('Try RSVP demo','جرّب التسجيل')}</button><p id="demo-rsvp-result" role="status"></p>`:''}`}
